@RestController
@RequestMapping("/user/zUser")
public class ZUserController {
    @Resource private ZUserService zUserService;

    @PostMapping("/add")
    public String add(@RequestBody ZUser user) {
        zUserService.save(user);
        return "success";
    }

    @GetMapping("/getById")
    public ZUser getById(String id) {
        return zUserService.getById(id);
    }
}
